SELECT Q.NO,Q.MEMBER_ID,Q.COURSE_NO,Q.SUBJECT,Q.STATUS,Q.HIT,TO_CHAR(Q.REGDATE,'yyyy-mm-dd') as REGDATE,c.title,M.NAME FROM COURSE_QNA Q JOIN COURSE C ON Q.COURSE_NO=C.NO JOIN MEMBER M ON Q.MEMBER_ID=M.MEMBER_ID WHERE C.INSTRUCTOR_NO=#{member_id}
AND status=#{status}
AND title=#{title}
ORDER BY Q.REGDATE DESC, Q.NO DESC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

